                                {"requestId":"pm-west-2","operator":"atc","routeId":"west",
                                 "routeVersion":1,"startSecond":10,"endSecond":20}"""))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.data.status").value("ACTIVE"));
    }

